import itertools, json
jobs='ABCDE'
slot=dict(zip(jobs, [[0,1,4,11,3],[2,3,3,2,5],[4,8,2,10,8],[3,2,11,3,4],[10,6,10,10,4]]))
t=dict(zip(jobs, [[0,3,3,0,5],[5,0,4,2,0],[2,2,0,2,5],[0,5,5,0,5],[1,4,3,1,0]]))
def nominal(r):
    return sum(slot[j][i] for i,j in enumerate(r))+sum(t[a][jobs.index(b)] for a,b in zip(r,r[1:]))
def incident(r,s):
    p={j:r.index(j)+1 for j in jobs}
    if p['A']>p['D']: return None
    if s=='rain':
        if p['D']==1 or p['A']==1: return None
        return nominal(r)+6*max(0,p['C']-1)
    if s=='road':
        if p['C']==4 or p['E']==2: return None
        return nominal(r)+6*max(0,p['D']-3)
    if p['A']==1 or p['B']==1: return None
    return nominal(r)+10*max(0,p['E']-2)
rows=[]
for tup in itertools.permutations(jobs):
    r=''.join(tup)
    if r.index('A')>r.index('D'): continue
    neighbors=[(r,0)]
    for i in range(5):
        for j in range(i+1,5):
            a=list(r); a[i],a[j]=a[j],a[i]
            neighbors.append((''.join(a),1))
    repairs={}; costs={}
    for s in ['rain','road','lift']:
        options=[(incident(q,s)+fee,q) for q,fee in neighbors if incident(q,s) is not None]
        if not options: break
        costs[s],repairs[s]=min(options)
    if len(costs)==3:
        rows.append((nominal(r)+max(costs.values()),r,repairs,costs))
rows.sort()
best=rows[0]
print(json.dumps(dict(roster=best[1],score=best[0],repairs=best[2],repair_costs=best[3],feasible_count=len(rows),next_score=min(x[0] for x in rows if x[0]>best[0]))))
# Independently evaluate the chosen repairs with explicit position lists and transfer lookup.
score,r,repairs,costs=best
assert len(rows)==len(set(x[1] for x in rows))
for s,q in repairs.items():
    assert sorted(q)==list(jobs) and q.index('A')<q.index('D')
    differences=[i for i in range(5) if q[i]!=r[i]]
    assert len(differences) in (0,2)
    if differences:
        i,j=differences
        assert r[i]==q[j] and r[j]==q[i]
    explicit=sum(slot[q[i]][i] for i in range(5))+sum(t[q[i]][jobs.index(q[i+1])] for i in range(4))
    late={'rain':6*max(q.index('C'),0),'road':6*max(q.index('D')-2,0),'lift':10*max(q.index('E')-1,0)}[s]
    assert explicit+late+bool(differences)==costs[s]
print('Verified chosen repair arithmetic and single-swap constraints; published nominal:',nominal(r))
print('Best rows:',rows[:3])

