import itertools,json
jobs='ABCDE'; published='AECBD'
slot=[[0,1,4,11,3],[2,3,3,2,5],[4,8,2,10,8],[3,2,11,3,4],[10,6,10,10,4]]
trans=[[0,3,3,0,5],[5,0,4,2,0],[2,2,0,2,5],[0,5,5,0,5],[1,4,3,1,0]]
# Breadth-first enumeration establishes minimum pair-exchange distances.
dist={published:0}; frontier=[published]
for depth in (1,2):
    following=[]
    for r in frontier:
        for i in range(5):
            for j in range(i+1,5):
                q=list(r);q[i],q[j]=q[j],q[i];q=''.join(q)
                if q not in dist:
                    dist[q]=depth;following.append(q)
    frontier=following
classes={str(d):[] for d in range(3)}
for r,d in dist.items():
    if r.index('A')>r.index('D') or r[0] in 'AD' or r[3]=='B':continue
    nominal=sum(slot[jobs.index(j)][i] for i,j in enumerate(r))+sum(trans[jobs.index(a)][jobs.index(b)] for a,b in zip(r,r[1:]))
    cost=nominal+6*r.index('C')+d+(4 if d==2 else 0)
    classes[str(d)].append((cost,r))
best=min(x for group in classes.values() for x in group)
result={'roster':best[1],'score':best[0],'best_by_swaps':{d:min(v)[0] if v else None for d,v in classes.items()},'feasible_by_swaps':{d:len(v) for d,v in classes.items()}}
# Independent permutation-cycle distance checks all reachable and unreachable rosters.
for p in itertools.permutations(jobs):
    r=''.join(p); mapping=[published.index(j) for j in r]; seen=set();cycles=0
    for i in range(5):
        if i not in seen:
            cycles+=1;k=i
            while k not in seen:seen.add(k);k=mapping[k]
    distance=5-cycles
    assert (r in dist)==(distance<=2)
    if r in dist:assert dist[r]==distance
print(json.dumps(result))
print('Best entries:',{d:sorted(v)[:3] for d,v in classes.items()})

